import { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { useInfiniteQuery } from '@tanstack/react-query';

interface UseInfiniteScrollOptions<T> {
  queryKey: string;
  cacheKey: string;
  fetchPage: (pageParam: number, filters: any) => Promise<{ data: T[]; totalItems: number; totalPages: number; meta?: Record<string, any> }>;
  serverFilters?: any;
  clientFilterFn?: (item: T) => boolean;
  pageSize?: number;
}

const globalModuleCache: Record<string, any[]> = {};
const globalTotalItems: Record<string, number> = {};
const globalMeta: Record<string, Record<string, any>> = {};

export const clearInfiniteScrollCache = (cacheKey?: string) => {
  if (cacheKey) {
    globalModuleCache[cacheKey] = [];
    globalTotalItems[cacheKey] = 0;
  } else {
    Object.keys(globalModuleCache).forEach(k => {
      globalModuleCache[k] = [];
      globalTotalItems[k] = 0;
    });
  }
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('clear-module-cache', { detail: { cacheKey } }));
  }
};

export function useInfiniteScroll<T>({
  queryKey,
  cacheKey,
  fetchPage,
  serverFilters = {},
  clientFilterFn,
}: UseInfiniteScrollOptions<T>) {
  const [items, setItems] = useState<T[]>(() => {
    return (globalModuleCache[cacheKey] as T[]) || [];
  });

  const [totalItems, setTotalItems] = useState<number>(() => {
    return globalTotalItems[cacheKey] || 0;
  });

  const [meta, setMeta] = useState<Record<string, any>>(() => {
    return globalMeta[cacheKey] || {};
  });

  // Listen for global cache clear events to update mounted states immediately
  useEffect(() => {
    const handleClear = (e: Event) => {
      const customEvent = e as CustomEvent;
      const targetKey = customEvent.detail?.cacheKey;
      if (!targetKey || targetKey === cacheKey) {
        setItems([]);
        setTotalItems(0);
        setMeta({});
      }
    };
    window.addEventListener('clear-module-cache', handleClear);
    return () => window.removeEventListener('clear-module-cache', handleClear);
  }, [cacheKey]);

  const prevFiltersRef = useRef<any>(serverFilters);

  // Clear cache and reset state when server filters change to prevent stale flash
  const filtersChanged = useMemo(() => {
    const changed = JSON.stringify(prevFiltersRef.current) !== JSON.stringify(serverFilters);
    if (changed) {
      prevFiltersRef.current = serverFilters;
    }
    return changed;
  }, [serverFilters]);

  useEffect(() => {
    if (filtersChanged) {
      globalModuleCache[cacheKey] = [];
      globalTotalItems[cacheKey] = 0;
      globalMeta[cacheKey] = {};
      setItems([]);
      setTotalItems(0);
      setMeta({});
    }
  }, [filtersChanged, cacheKey]);

  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetching,
    isFetchingNextPage,
    refetch,
  } = useInfiniteQuery({
    queryKey: [queryKey, serverFilters],
    queryFn: async ({ pageParam = 1 }) => {
      const res = await fetchPage(pageParam, serverFilters);
      return res;
    },
    initialPageParam: 1,
    getNextPageParam: (lastPage, allPages) => {
      const currentPage = allPages.length;
      if (currentPage >= lastPage.totalPages) {
        return undefined;
      }
      return currentPage + 1;
    },
    staleTime: 1 * 60 * 1000,     // 1 minute
    gcTime: 8 * 60 * 60 * 1000,   // 8 hours — never evict during a full working day
    refetchOnMount: true,          // serve module cache instantly, refetch in background if needed
  });

  // Sync React Query data with local state & module cache
  useEffect(() => {
    if (data && data.pages.length > 0) {
      const flat = data.pages.flatMap(page => page.data);
      globalModuleCache[cacheKey] = flat.slice(0, 200); // Cap in-memory module cache to 200 items
      
      const lastPage = data.pages[data.pages.length - 1];
      if (lastPage && typeof lastPage.totalItems === 'number') {
        globalTotalItems[cacheKey] = lastPage.totalItems;
        setTotalItems(lastPage.totalItems);
      }
      if (lastPage && lastPage.meta) {
        globalMeta[cacheKey] = lastPage.meta;
        setMeta(lastPage.meta);
      }

      setItems(flat);
    }
  }, [data, cacheKey]);

  // Keep latest dependencies in a ref to avoid stale closures in stable callback
  const latestDepsRef = useRef({ hasNextPage, fetchNextPage, isFetching, isFetchingNextPage });
  latestDepsRef.current = { hasNextPage, fetchNextPage, isFetching, isFetchingNextPage };

  // intersection observer for loading more items when scrolling to the bottom
  const observerRef = useRef<IntersectionObserver | null>(null);
  const sentinelRef = useCallback((node: HTMLDivElement | null) => {
    if (observerRef.current) {
      observerRef.current.disconnect();
      observerRef.current = null;
    }

    if (node) {
      observerRef.current = new IntersectionObserver(entries => {
        const { hasNextPage: hasNext, fetchNextPage: fetchNext, isFetching: fetching, isFetchingNextPage: fetchingNext } = latestDepsRef.current;
        if (entries[0].isIntersecting && hasNext && !fetching && !fetchingNext) {
          fetchNext();
        }
      });
      observerRef.current.observe(node);
    }
  }, []);

  // Apply synchronous client-side filtering on the retrieved list
  const filteredItems = useMemo(() => {
    return clientFilterFn ? items.filter(clientFilterFn) : items;
  }, [items, clientFilterFn]);

  return {
    items: filteredItems,
    allItems: items,
    totalItems,
    meta,
    isFetching,
    isFetchingNextPage,
    hasNextPage,
    fetchNextPage,
    refetch,
    sentinelRef,
  };
}

import axios from 'axios';

// Vite handles the proxy in dev mode to http://localhost:3000
const API_URL = '/api';

export const apiClient = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Utility for API Data Standardization (snake_case -> camelCase)
// This is the implementation of the missing data standardizer layer
// DO NOT globally enable this interceptor yet as it will break 432+ legacy UI elements.
// Instead, new modules should use `apiClient.get('/path', { standardizeData: true })`
export const toCamelCase = (str: string): string => {
  return str.replace(/([-_][a-z])/ig, ($1) => {
    return $1.toUpperCase()
      .replace('-', '')
      .replace('_', '');
  });
};

export const objectToCamelCase = (obj: any): any => {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }
  
  if (Array.isArray(obj)) {
    return obj.map(item => objectToCamelCase(item));
  }
  
  return Object.keys(obj).reduce((result, key) => {
    const camelKey = toCamelCase(key);
    result[camelKey] = objectToCamelCase(obj[key]);
    return result;
  }, {} as Record<string, any>);
};

// Extend Axios request config to support standardization flag
declare module 'axios' {
  export interface AxiosRequestConfig {
    standardizeData?: boolean;
    _rateLimitRetryCount?: number;
  }
}

// Interceptor to handle errors centrally and OPTIONAL data standardization
apiClient.interceptors.response.use(
  (response) => {
    // Check if the caller opted into data standardization
    if (response.config && response.config.standardizeData && response.data) {
      response.data = objectToCamelCase(response.data);
    }
    return response;
  },
  async (error) => {
    const config = error.config;

    // If 503 Service Initializing, retry with backoff. A truly fresh install
    // (no pre-existing DB, unlike a dev machine reusing one) can take longer
    // than a few seconds to finish creating the schema on first-ever launch,
    // so this budget is generous (up to ~34s) rather than a flat 5x1s.
    if (error.response?.status === 503) {
      const maxRetries = 12;
      if (config && (!config._retryCount || config._retryCount < maxRetries)) {
        config._retryCount = (config._retryCount || 0) + 1;
        const baseDelay = (error.response?.data?.retryAfter || 1) * 1000;
        const delay = Math.min(baseDelay * config._retryCount, 5000);
        console.warn(`[API] Server is initializing. Retrying ${config.url} (Attempt ${config._retryCount}/${maxRetries}) in ${delay}ms...`);
        await new Promise((resolve) => setTimeout(resolve, delay));
        return apiClient(config);
      }
    }

    // If 429 Too Many Requests, retry with exponential backoff rather than failing page rendering outright
    if (error.response?.status === 429) {
      const maxRetries = 3;
      if (config && (!config._rateLimitRetryCount || config._rateLimitRetryCount < maxRetries)) {
        config._rateLimitRetryCount = (config._rateLimitRetryCount || 0) + 1;
        const retryAfterHeader = error.response?.headers?.['retry-after'];
        const retryAfterMs = retryAfterHeader ? parseInt(retryAfterHeader, 10) * 1000 : 0;
        const backoffDelay = retryAfterMs || Math.min(1000 * Math.pow(2, config._rateLimitRetryCount - 1), 4000);
        console.warn(`[API] 429 Rate limited on ${config.url}. Retrying (Attempt ${config._rateLimitRetryCount}/${maxRetries}) in ${backoffDelay}ms...`);
        await new Promise((resolve) => setTimeout(resolve, backoffDelay));
        return apiClient(config);
      }
    }

    // Retry safe GET requests up to 3 times on transient network error/timeout
    const isGet = config && config.method && config.method.toLowerCase() === 'get';
    const isNetworkError = !error.response || error.code === 'ECONNABORTED' || error.message === 'Network Error';
    if (isGet && isNetworkError) {
      if (config && (!config._retryCount || config._retryCount < 3)) {
        config._retryCount = (config._retryCount || 0) + 1;
        console.warn(`[API] Transient network error on GET. Retrying ${config.url} (Attempt ${config._retryCount}/3)...`);
        await new Promise((resolve) => setTimeout(resolve, 1500));
        return apiClient(config);
      }
    }

    // Diagnostics check for false backend errors — result attached to the rejected error so callers can inspect it
    if (isNetworkError && config && config.url !== '/verification/health' && config.url !== '/api/verification/health') {
      console.warn(`[Verification Layer] Request to ${config.url} failed. Performing silent health check...`);
      axios.get('/api/verification/health')
      .then(res => {
        if (res.data && res.data.success) {
          const msg = `Backend & DB healthy — endpoint-specific issue on: ${config.url}`;
          console.error(`[Verification Layer] Diagnostics: ${msg}`);
          (error as any)._diagnostics = msg;
        } else {
          const msg = `Database or backend failure: ${res.data?.message || 'Unknown'}`;
          console.error(`[Verification Layer] Diagnostics: ${msg}`);
          (error as any)._diagnostics = msg;
        }
      })
      .catch(healthErr => {
        const msg = `Backend fully unreachable: ${healthErr.message}`;
        console.error(`[Verification Layer] Diagnostics: ${msg}`);
        (error as any)._diagnostics = msg;
      });
    }

    // Basic global error handling
    if (error.response?.status === 401) {
      console.warn('Unauthorized request. Token might be missing or invalid.');
    }
    return Promise.reject(error);
  }
);

